"""Topic path subscription matcher."""
def is_topic_subscribed(subscribed_topic_root: str, event_topic_root: str) -> bool:
    """Determine if an event's root topic matches the subscribed root topic."""
    return event_topic_root == subscribed_topic_root

def clean_topic_segment(topic: str) -> str:
    return topic.strip().lower()

def is_wildcard_subscription(pattern: str) -> bool:
    return pattern.strip() in ("*", "**")
